import { describe, expect, it } from 'vitest';
import fixture from '../../docs/specs/studio-observed-authoring/contracts/v3/publication-fixtures.json' with { type: 'json' };
import { deriveObservedArtifact, validateObservedRequest, validateReplayArtifact } from '../src/validator/observedReplay.js';
import { hashObserved, OBSERVED_PROFILE, OBSERVED_SCHEMA_BUNDLE_HASH, validateObserved } from '../src/validator/observedReferencePolicy.js';

const build = { ...fixture.build, schemaBundleHash: OBSERVED_SCHEMA_BUNDLE_HASH };
const versions = {
  contract: 3, learnedPlan: 3, observation: 3, guidedPolicy: 3,
  referencePolicy: 4, lowering: 2, artifact: 3, language: 'observed-3', executor: 'observed-4',
};

describe('active observed v3 admission and publication tuple', () => {
  it('accepts the full admitted v3 proof through derivation, artifact validation and request validation', () => {
    expect(fixture.basis.preparations.length).toBeGreaterThan(0);
    for (const preparation of fixture.basis.preparations) expect(preparation.proof.versions).toEqual(versions);
    const derived = deriveObservedArtifact(fixture.basis);
    expect(derived.artifact).toEqual(fixture.artifact);
    expect(derived.artifact.profile).toEqual(OBSERVED_PROFILE);
    expect(derived.artifact.learnedPlan.versions).toEqual(versions);
    expect(validateReplayArtifact(derived.artifact)).toEqual(derived.artifact);
    expect(validateObservedRequest({ ...fixture.validationRequest, requiredBuild: build }, build)).toMatchObject({
      ok: true, errorCode: null, artifactHash: hashObserved(fixture.artifact),
    });
  });

  it('refuses an old v2 proof tuple instead of activating a fallback', () => {
    const basis = structuredClone(fixture.basis);
    const proof = basis.preparations[0]?.proof;
    if (!proof) throw new Error('Missing admitted proof fixture');
    proof.versions = { contract: 2, learnedPlan: 2, observation: 2, guidedPolicy: 2,
      referencePolicy: 3, lowering: 1, artifact: 2, language: 'observed-2', executor: 'observed-2' };
    expect(() => deriveObservedArtifact(basis)).toThrow('INVALID_CONTRACT');
  });
  it('rejects the superseded observed-3 executor and observed-replay-2 catalog while retaining language observed-3',()=>{
    const basis=structuredClone(fixture.basis);const proof=basis.preparations[0]?.proof;if(!proof)throw new Error('PROOF');
    (proof.versions as {executor:string}).executor='observed-3';expect(()=>deriveObservedArtifact(basis)).toThrow('INVALID_CONTRACT');
    const artifact=structuredClone(fixture.artifact);(artifact.profile as {catalog:string}).catalog='observed-replay-2';expect(()=>validateReplayArtifact(artifact)).toThrow();
    expect(OBSERVED_PROFILE.language).toBe('observed-3');expect(OBSERVED_PROFILE.executor).toBe('observed-4');expect(OBSERVED_PROFILE.catalog).toBe('observed-replay-3');
  });

  it.each(Object.keys(versions) as (keyof typeof versions)[])('refuses a single mutated %s proof pin', key => {
    const basis = structuredClone(fixture.basis);
    const proof = basis.preparations[0]?.proof;
    if (!proof) throw new Error('Missing admitted proof fixture');
    const pins: Record<string, string | number> = proof.versions;
    const current = pins[key];
    pins[key] = typeof current === 'number' ? current + 1 : 'observed-invalid';
    expect(() => deriveObservedArtifact(basis)).toThrow('INVALID_CONTRACT');
  });
});


describe('v3 observed-choice response provenance', () => {
  const witness = () => {
    const preparation = fixture.observedChoice.basis.preparations[3];
    if (!preparation || !('observedChoice' in preparation) || !preparation.observedChoice) {
      throw new Error('Missing independently sealed observed-choice witness');
    }
    return structuredClone(preparation.observedChoice);
  };

  it('accepts the actual v3 model response leaf in a complete legitimate witness and sealed artifact', () => {
    const value = witness();
    expect(value.attempt.responseSchemaVersion).toBe(3);
    validateObserved('replay-validation#/definitions/QuestionAttemptEvidence', value.attempt);
    validateObserved('replay-validation#/definitions/ObservedChoiceWitness1', value);
    expect(deriveObservedArtifact(fixture.observedChoice.basis)).toEqual({
      artifact: fixture.observedChoice.artifact,
      hashes: fixture.observedChoice.hashes,
    });
  });

  it.each(['version2', 'missing-version', 'extra-member'] as const)(
    'refuses %s without weakening the closed v3 witness', mutation => {
      const value = witness();
      const attempt = value.attempt as Record<string, unknown>;
      if (mutation === 'version2') attempt.responseSchemaVersion = 2;
      else if (mutation === 'missing-version') delete attempt.responseSchemaVersion;
      else attempt.unexpectedMember = true;
      expect(() => validateObserved(
        'replay-validation#/definitions/QuestionAttemptEvidence', attempt,
      )).toThrow('INVALID_CONTRACT');
      expect(() => validateObserved(
        'replay-validation#/definitions/ObservedChoiceWitness1', value,
      )).toThrow('INVALID_CONTRACT');
    },
  );
});

